parameters.jsCode:
const body = $input.first().json.body;

const required = ['meeting_notes', 'meeting_title'];
const missing = required.filter(f => !body[f]);
if (missing.length) {
  return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
}

if (body.meeting_notes.trim().length < 50) {
  return [{ json: { valid: false, error: 'Notes too short — paste at least a few sentences' } }];
}

const validTypes = ['standup', 'planning', 'retrospective', 'client_call', 'one_on_one', 'all_hands', 'brainstorm', 'interview', 'other'];
const meetingType = validTypes.includes(body.meeting_type) ? body.meeting_type : 'other';

return [{
  json: {
    valid: true,
    meetingTitle: body.meeting_title.trim(),
    meetingType,
    meetingDate: body.meeting_date || new Date().toISOString().split('T')[0],
    attendees: Array.isArray(body.attendees) ? body.attendees : (body.attendees || '').split(',').map(a => a.trim()).filter(Boolean),
    meetingNotes: body.meeting_notes.trim().slice(0, 8000),
    organizerEmail: body.organizer_email || null,
    sendSummaryTo: Array.isArray(body.send_summary_to) ? body.send_summary_to : (body.send_summary_to || '').split(',').map(e => e.trim()).filter(Boolean),
    projectName: body.project_name || '',
    slackChannel: body.slack_channel || null,
    requestedAt: new Date().toISOString()
  }
}];

values.content:
Extract structured information from these meeting notes.

Meeting: {{ $json.meetingTitle }}
Type: {{ $json.meetingType }}
Date: {{ $json.meetingDate }}
Attendees: {{ $json.attendees.join(', ') || 'not specified' }}
Project: {{ $json.projectName || 'not specified' }}

Notes:
{{ $json.meetingNotes }}

Return this JSON:
{
  "meeting_summary": "3-4 sentence summary of what happened in this meeting — what was discussed, what was decided, what's the overall status",
  "key_decisions": [
    {
      "decision": "what was decided",
      "rationale": "why if mentioned",
      "impact": "who or what this affects"
    }
  ],
  "action_items": [
    {
      "id": "A1",
      "task": "specific task description",
      "owner": "person's name or 'unassigned'",
      "due_date": "deadline if mentioned or 'not specified'",
      "priority": "one of: urgent | high | medium | low",
      "context": "why this matters or what it unblocks — one sentence"
    }
  ],
  "open_questions": [
    {
      "question": "what still needs to be answered",
      "raised_by": "who asked if known",
      "needed_by": "when an answer is needed if mentioned"
    }
  ],
  "blockers": [
    {
      "blocker": "what is blocking progress",
      "affects": "what work or who is blocked",
      "owner": "who needs to resolve it"
    }
  ],
  "follow_up_meeting_needed": true or false,
  "suggested_next_meeting_agenda": ["agenda items for next meeting if relevant — leave empty if not needed"],
  "parking_lot": ["topics raised but deliberately deferred — do not confuse with action items"]
}

parameters.jsCode:
const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let extracted;
try {
  extracted = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch(e) {
  return [{ json: { error: 'Parse error', raw } }];
}

const input = $('Validate Input').first().json;
extracted._meta = {
  meetingTitle: input.meetingTitle,
  meetingDate: input.meetingDate,
  meetingType: input.meetingType,
  attendees: input.attendees,
  projectName: input.projectName,
  organizerEmail: input.organizerEmail,
  sendSummaryTo: input.sendSummaryTo,
  slackChannel: input.slackChannel
};

return [{ json: extracted }];

const d = $input.first().json;
const m = d._meta;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const priorityColor = { urgent: '#dc2626', high: '#d97706', medium: '#2563eb', low: '#6b7280' };
const priorityBg = { urgent: '#fef2f2', high: '#fffbeb', medium: '#eff6ff', low: '#f9fafb' };

const actionRows = (d.action_items || []).map(a => `
  <tr style="border-bottom:1px solid #f0f0f0">
    <td style="padding:10px 12px;font-family:monospace;font-size:12px;color:#888;white-space:nowrap">${esc(a.id)}</td>
    <td style="padding:10px 12px">
      <div style="font-size:14px;font-weight:500;color:#1a1a1a">${esc(a.task)}</div>
      ${a.context ? `<div style="font-size:12px;color:#888;margin-top:3px">${esc(a.context)}</div>` : ''}
    </td>
    <td style="padding:10px 12px;font-size:13px;color:#555;white-space:nowrap">${esc(a.owner)}</td>
    <td style="padding:10px 12px;font-size:13px;color:#555;white-space:nowrap">${esc(a.due_date)}</td>
    <td style="padding:10px 12px">
      <span style="background:${priorityBg[a.priority]||'#f9fafb'};color:${priorityColor[a.priority]||'#6b7280'};font-size:11px;font-weight:700;padding:2px 8px;border-radius:10px;text-transform:uppercase">${esc(a.priority)}</span>
    </td>
  </tr>`).join('');

const decisionBlocks = (d.key_decisions || []).map(dec =>
  `<div style="padding:10px 0;border-bottom:1px solid #f0fdf4">
    <div style="font-size:14px;font-weight:600;color:#1a1a1a">${esc(dec.decision)}</div>
    ${dec.rationale ? `<div style="font-size:13px;color:#555;margin-top:3px">${esc(dec.rationale)}</div>` : ''}
    ${dec.impact ? `<div style="font-size:12px;color:#888;margin-top:2px">Affects: ${esc(dec.impact)}</div>` : ''}
  </div>`).join('');

const questionBlocks = (d.open_questions || []).map(q =>
  `<div style="font-size:14px;padding:7px 0;border-bottom:1px solid #fef9c3;color:#555">
    ❓ ${esc(q.question)}
    ${q.raised_by ? `<span style="font-size:12px;color:#aaa"> — raised by ${esc(q.raised_by)}</span>` : ''}
    ${q.needed_by ? `<span style="font-size:12px;color:#d97706"> · needed by ${esc(q.needed_by)}</span>` : ''}
  </div>`).join('');

const blockerBlocks = (d.blockers || []).map(b =>
  `<div style="border-left:3px solid #dc2626;padding:8px 14px;background:#fef2f2;border-radius:0 4px 4px 0;margin-bottom:8px">
    <div style="font-size:14px;font-weight:600;color:#7f1d1d">${esc(b.blocker)}</div>
    <div style="font-size:12px;color:#991b1b;margin-top:2px">Blocks: ${esc(b.affects)} · Owner: ${esc(b.owner)}</div>
  </div>`).join('');

const urgentCount = (d.action_items||[]).filter(a => a.priority === 'urgent').length;
const unassignedCount = (d.action_items||[]).filter(a => a.owner === 'unassigned').length;

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:16px;background:#f5f5f3;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#1a1a1a">
<div style="max-width:700px;margin:0 auto">

  <div style="background:#18181b;color:#fff;padding:20px 28px;border-radius:10px 10px 0 0">
    <div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#71717a;margin-bottom:5px">${esc(m.meetingType.replace(/_/g,' '))} · ${esc(m.meetingDate)}${m.projectName ? ' · ' + esc(m.projectName) : ''}</div>
    <div style="font-size:19px;font-weight:700">${esc(m.meetingTitle)}</div>
    <div style="margin-top:8px;font-size:13px;color:#a1a1aa">
      ${(d.action_items||[]).length} action items
      ${urgentCount > 0 ? ` · <span style="color:#f87171">${urgentCount} urgent</span>` : ''}
      ${unassignedCount > 0 ? ` · <span style="color:#fbbf24">${unassignedCount} unassigned</span>` : ''}
      ${(d.blockers||[]).length > 0 ? ` · <span style="color:#f87171">${d.blockers.length} blocker${d.blockers.length > 1 ? 's' : ''}</span>` : ''}
    </div>
  </div>

  <div style="background:#fff;padding:18px 28px;border:1px solid #eee;border-top:none">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#888;margin-bottom:8px">Summary</div>
    <p style="font-size:15px;line-height:1.7;color:#333;margin:0">${esc(d.meeting_summary)}</p>
  </div>

  ${(d.action_items||[]).length ? `<div style="background:#fff;padding:18px 28px;border:1px solid #eee;border-top:3px solid #f0f0f0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#888;margin-bottom:12px">Action items</div>
    <table style="width:100%;border-collapse:collapse">
      <thead><tr style="background:#f8f8f8;font-size:11px;text-transform:uppercase;color:#aaa;letter-spacing:0.3px">
        <th style="padding:7px 12px;text-align:left">#</th>
        <th style="padding:7px 12px;text-align:left">Task</th>
        <th style="padding:7px 12px;text-align:left">Owner</th>
        <th style="padding:7px 12px;text-align:left">Due</th>
        <th style="padding:7px 12px;text-align:left">Priority</th>
      </tr></thead>
      <tbody>${actionRows}</tbody>
    </table>
  </div>` : ''}

  ${(d.key_decisions||[]).length ? `<div style="background:#f0fdf4;padding:18px 28px;border:1px solid #bbf7d0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#16a34a;margin-bottom:10px">✅ Decisions made</div>
    ${decisionBlocks}
  </div>` : ''}

  ${(d.blockers||[]).length ? `<div style="background:#fff;padding:18px 28px;border:1px solid #eee;border-top:3px solid #f0f0f0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#dc2626;margin-bottom:10px">🚧 Blockers</div>
    ${blockerBlocks}
  </div>` : ''}

  ${(d.open_questions||[]).length ? `<div style="background:#fefce8;padding:18px 28px;border:1px solid #fde68a">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#92400e;margin-bottom:10px">Open questions</div>
    ${questionBlocks}
  </div>` : ''}

  ${(d.parking_lot||[]).length ? `<div style="background:#fff;padding:14px 28px;border:1px solid #eee;border-top:3px solid #f0f0f0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#9ca3af;margin-bottom:8px">Parking lot</div>
    ${d.parking_lot.map(p => `<div style="font-size:13px;color:#6b7280;padding:4px 0">${esc(p)}</div>`).join('')}
  </div>` : ''}

  ${d.follow_up_meeting_needed && (d.suggested_next_meeting_agenda||[]).length ? `<div style="background:#f5f3ff;padding:14px 28px;border:1px solid #ddd6fe">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#7c3aed;margin-bottom:8px">Suggested next meeting agenda</div>
    ${d.suggested_next_meeting_agenda.map((item, i) => `<div style="font-size:14px;color:#555;padding:4px 0">${i+1}. ${esc(item)}</div>`).join('')}
  </div>` : ''}

  <div style="background:#18181b;color:#555;font-size:11px;padding:12px 28px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">
    Meeting Notes Extractor · ${esc(m.meetingDate)}${m.attendees.length ? ' · ' + esc(m.attendees.join(', ')) : ''}
  </div>
</div>
</body></html>`;

return [{ json: { html, actionCount: (d.action_items||[]).length, urgentCount, blockerCount: (d.blockers||[]).length, sendSummaryTo: m.sendSummaryTo, slackChannel: m.slackChannel, meetingTitle: m.meetingTitle, extracted: d } }];

